/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: album, catalogItem, itemName, mount
 * Tests
 *   - Album inventory uses its private cover and title as one detail entry without repeated management actions
 *   - Album details display the saved cover and keep all management actions behind the detail entry
 *   - invalid catalog category falls back to Albums and category switches update the visible inventory
 *   - existing catalog save is explicit, partial and preserves unsaved edits on revision conflict
 *   - lost catalog response retries the same intent and leaving Admin destroys its private preview
 *   - late catalog read cannot revert a confirmed mutation
 *   - a transient catalog failure retains the account-fenced draft and its revision
 *   - Page visibility patches only the confirmed occurrence and its captured page revision
 *   - Page placements keep missing and unsupported references identifiable
 *   - a placement rename or source change invalidates its open visibility approval
 *   - manual confirmation shows exactly the frozen partial patch and omits unchanged fields
 *   - a stale confirmation explains recovery, preserves edits on cancel, and requires a fresh snapshot
 *   - offline and failed reads do not masquerade as a stale confirmation
 *   - an unknown manual operation permits read-only refresh while retaining its exact intent and unsaved values
 *   - historical cover cleanup preserves dirty manual values and exposes a changed saved revision for explicit review
 *   - historical cover cancellation binds the latest saved owner while retaining an older dirty manual baseline
 *   - reverting a draft after observing a newer revision retains the explicit recovery path
 *   - a stored Disc Number appears in MediaTrack metadata before the Track Number
 *   - join phrases are edited between names and mirror the successor rule locally
 *   - adding a Credit clears the previous last phrase and keeps every other phrase
 *   - confirmation distinguishes unavailable Credits from explicit removal and includes coupled attribution
 *   - same-named Credit replacements remain distinguishable by their exact records
 *   - an Artist's MusicBrainz ID is edited as trimmed lowercase text, cleared when emptied, and an ID another Artist keeps is refused with its own message
 *   - an Organization's saved MusicBrainz ID is shown, and clearing it confirms the stored ID against none and sends only null
 * @end-catalog */

import { act, cleanup, fireEvent, render, screen, waitFor, within } from '@testing-library/react';
import { QueryClient, QueryClientProvider, onlineManager } from '@tanstack/react-query';
import { MemoryRouter } from 'react-router';
import { captureAccountOperation } from '../../api/accountEpoch';
import { adminWorkspace } from './adminWorkspace';
import { AdminCatalogPage } from './AdminCatalogPage';
import { CatalogEditConfirmation } from './CatalogEditConfirmation';
import { catalogPatch } from './catalogApi';
import { AdminPagesPage } from './AdminPagesPage';
import { deferred, json, session, viewer } from './adminFixtures.testSupport';
import type { CatalogItem, CatalogKind } from './catalogApi';
// The Album page's Tracks section reads its own endpoint and is covered by CatalogAlbumTracks.test.tsx.
vi.mock('./CatalogAlbumTracks', () => ({ CatalogAlbumTracks: () => null }));
const album = (): Extract<CatalogItem, { kind: 'album' }> => ({ kind: 'album', id: '111111111111111111111111', revision: `cr_${'a'.repeat(43)}`, visibility: 'public', effectiveVisibility: 'public', coverUrl: null, mediaUrl: null, capabilities: { editing: true, visibility: true }, fields: { title: 'Synthetic catalog Album', releaseDate: null, credits: null, attributionStatus: 'unknown' } });
function catalogItem(kind: CatalogKind): CatalogItem {
  const base = album();
  if (kind === 'artist') return { ...base, kind, fields: { name: 'Synthetic artist', bio: '', birthDate: null, musicBrainzId: null } };
  if (kind === 'organization') return { ...base, kind, fields: { name: '𠮷 Synthetic organization', description: '', organizationType: 'archive', musicBrainzId: null } };
  if (kind === 'audioTrack') return { ...base, kind, fields: { ...base.fields, title: 'Synthetic track', releaseDate: { year: 2023, month: 4, day: null }, discNumber: null, trackNumber: 2 } };
  return base;
}
const itemName = (item: CatalogItem) => 'name' in item.fields ? item.fields.name : item.fields.title;
function mount(element: React.ReactNode, path = '/') { const client = new QueryClient({ defaultOptions: { queries: { retry: false } } }); client.setQueryData(['browser-session'], session); render(<QueryClientProvider client={client}><MemoryRouter initialEntries={[path]}>{element}</MemoryRouter></QueryClientProvider>); return client; }
beforeEach(() => { adminWorkspace.reset(); adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true }); adminWorkspace.select('admin'); });
afterEach(() => { cleanup(); adminWorkspace.reset(); vi.unstubAllGlobals(); vi.restoreAllMocks(); onlineManager.setOnline(true); });
test('Album inventory uses its private cover and title as one detail entry without repeated management actions', async () => {
  const item = { ...album(), coverUrl: '/api/admin/v1/catalog/album/111111111111111111111111/artwork', fields: { ...album().fields, releaseDate: { year: 2024, month: null, day: null } } };
  adminWorkspace.authorize(captureAccountOperation(viewer), true, true, undefined, { editing: true, visibility: true }, true);
  vi.stubGlobal('fetch', vi.fn(async () => json({ items: [item], nextCursor: null })));
  mount(<AdminCatalogPage />);
  const link = await screen.findByRole('link', { name: item.fields.title });
  expect(link).toHaveAttribute('href', `/admin/catalog/album/${item.id}`);
  expect(link).toHaveAccessibleDescription('Public · 2024');
  const image = link.querySelector('img')!;
  expect(image).toHaveAttribute('src', `${item.coverUrl}?viewer=${viewer}`);
  expect(image).toHaveAttribute('alt', ''); expect(image).not.toHaveAttribute('srcset');
  expect(screen.queryByRole('link', { name: 'Edit manually' })).not.toBeInTheDocument();
  expect(screen.queryByRole('button', { name: 'Review existing Album' })).not.toBeInTheDocument();
  expect(screen.queryByRole('link', { name: 'Convert to MP3' })).not.toBeInTheDocument();
  act(() => adminWorkspace.select('user')); expect(document.querySelector('img')).toBeNull();
});

